#include <string>
#include <sstream>
bool parseChoice(const std::string& line, int low, int high, int& value) {
    std::istringstream input(line); int candidate; char extra;
    if (!(input >> candidate) || (input >> extra) || candidate < low || candidate > high) return false;
    value = candidate; return true;
}

